import pytest

from solution import intersperse

def test_intersperse_empty_list():
    assert intersperse([], 4) == []

def test_intersperse_single_element_list():
    assert intersperse([1], 4) == [1]

def test_intersperse_two_elements_list():
    assert intersperse([1, 2], 4) == [1, 4, 2]

def test_intersperse_three_elements_list():
    assert intersperse([1, 2, 3], 4) == [1, 4, 2, 4, 3]

def test_intersperse_large_list():
    large_list = list(range(10))
    delimeter = 5
    expected_result = [i for i in range(10)] + [delimeter] * 9
    assert intersperse(large_list, delimeter) == expected_result

def test_intersperse_with_zero_delimiter():
    assert intersperse([1, 2, 3], 0) == [1, 0, 2, 0, 3]

def test_intersperse_with_negative_delimiter():
    assert intersperse([1, 2, 3], -1) == [1, -1, 2, -1, 3]

def test_intersperse_with_float_delimiter():
    assert intersperse([1, 2, 3], 1.5) == [1, 1.5, 2, 1.5, 3]

def test_intersperse_with_non_integer_delimiter():
    with pytest.raises(TypeError):
        intersperse([1, 2, 3], "a")
